#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;

long long power(long long base, long long exp, long long mod) {
    long long result = 1LL;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        exp >>= 1;
        base = (base * base) % mod;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long N, M, L, R;
    cin >> N >> M >> L >> R;

    long long total = N * M;
    __int128 totalExp = (__int128)total;
    __int128 rangeSize = (__int128)(R - L + 1);
    long long mod = MOD;

    if ((N * M) % 2 == 1) {
        __int128 res = 1;
        __int128 base = rangeSize % mod;
        __int128 exp = totalExp;
        // Modular exponentiation
        __int128 b = base;
        __int128 e = exp;
        __int128 result = 1;
        while (e > 0) {
            if (e & 1) {
                result = (result * b) % mod;
            }
            e >>= 1;
            b = (b * b) % mod;
        }
        res = result;
        cout << (long long)((res + mod) % mod) << "\n";
    } else {
        __int128 res = 1;
        __int128 base = rangeSize % mod;
        __int128 exp = totalExp;
        // Modular exponentiation
        __int128 b = base;
        __int128 e = exp;
        __int128 result = 1;
        while (e > 0) {
            if (e & 1) {
                result = (result * b) % mod;
            }
            e >>= 1;
            b = (b * b) % mod;
        }
        res = result;
        if ((R - L) % 2 == 0) {
            res = (res + 1) % mod;
        }
        long long invTwo = power(2, MOD - 2, MOD);
        res = (res * invTwo) % mod;
        cout << (long long)res << "\n";
    }
    return 0;
}

